// ApiService.js
const API_BASE_URL = 'http://localhost:3188/Studio/Reels';

class ApiService {

    // ==========================
    // 🔵 GET UNIVERSAL HELPER
    // ==========================
    static async get(url) {
        const response = await fetch(url, {
            method: 'GET',
            headers: {
                'Content-Type': 'application/json'
            },
            credentials: 'include'
        });

        if (!response.ok) {
            const err = await response.text();
            throw new Error(err || `HTTP Error: ${response.status}`);
        }

        return response.json();
    }

    // ==========================
    // 🔵 POST UNIVERSAL HELPER
    // ==========================
    static async post(url, body) {
        const response = await fetch(url, {
            method: 'POST',
            headers: {
                'Content-Type': 'application/json'
            },
            credentials: 'include',
            body: JSON.stringify(body)
        });

        if (!response.ok) {
            const err = await response.text();
            throw new Error(err || `HTTP Error: ${response.status}`);
        }

        return response.json();
    }

    // ==========================
    // 🔵 PUT UNIVERSAL HELPER
    // ==========================
    static async put(url, body) {
        const response = await fetch(url, {
            method: 'PUT',
            headers: {
                'Content-Type': 'application/json'
            },
            credentials: 'include',
            body: JSON.stringify(body)
        });

        if (!response.ok) {
            const err = await response.text();
            throw new Error(err || `HTTP Error: ${response.status}`);
        }

        return response.json();
    }

    // ==========================
    // 🔵 DELETE UNIVERSAL HELPER
    // ==========================
    static async delete(url) {
        const response = await fetch(url, {
            method: 'DELETE',
            headers: {
                'Content-Type': 'application/json'
            },
            credentials: 'include'
        });

        if (!response.ok) {
            const err = await response.text();
            throw new Error(err || `HTTP Error: ${response.status}`);
        }

        return response.json();
    }

    // ==========================
    // 🔵 GET SELLERS
    // ==========================
    static getSellers() {
        return this.get(`${API_BASE_URL}/sellers`);
    }

    // ==========================
    // 🔵 GET SELLER PRODUCTS
    // ==========================
    static getSellerProducts(vendorId) {
        return this.get(`${API_BASE_URL}/sellers/${vendorId}/products`);
    }

    // ==========================
    // 🔵 GET BRANDS
    // ==========================
    static getBrands() {
        return this.get(`${API_BASE_URL}/brands`);
    }

    // ==========================
    // 🔵 GET BRAND PRODUCTS
    // ==========================
    static getBrandProducts(brandId) {
        return this.get(`${API_BASE_URL}/brands/${brandId}/products`);
    }

    // ==========================
    // 🔵 GET CATEGORIES
    // ==========================
    static getCategories() {
        return this.get(`${API_BASE_URL}/categories`);
    }

    // ==========================
    // 🔵 UPLOAD REEL (FORM DATA)
    // ==========================
    static async uploadReel(formData) {
        try {
            const response = await fetch(`${API_BASE_URL}/upload`, {
                method: 'POST',
                body: formData,
                credentials: 'include' // VERY IMPORTANT
            });

            if (!response.ok) {
                let msg = "";
                try {
                    msg = (await response.json()).message;
                } catch {
                    msg = await response.text();
                }
                throw new Error(msg || `Upload failed (${response.status})`);
            }

            return response.json();
        } catch (error) {
            console.error('Error uploading reel:', error);
            throw error;
        }
    }

    // ==========================
    // 🔵 GET REELS FOR INFLUENCER
    // ==========================
    static getInfluencerReels() {
        return this.get(`${API_BASE_URL}/my-reels`);
    }

    // ==========================
    // 🔵 GET RELATED PRODUCTS
    // ==========================
    static getRelatedProducts(selectedProductIds, associationType, vendorId, brandId) {
        return this.post(`${API_BASE_URL}/related-products`, {
            selectedProductIds,
            associationType,
            vendorId,
            brandId
        });
    }

    // ==========================
    // 🔵 GET REEL BY ID
    // ==========================
    static getReelById(id) {
        return this.get(`${API_BASE_URL}/${id}`);
    }

    // ==========================
    // 🔵 EDIT REEL
    // ==========================
    static editReel(id, reelData) {
        return this.put(`${API_BASE_URL}/${id}`, reelData);
    }

    // ==========================
    // 🔵 DELETE REEL
    // ==========================
    static deleteReel(id) {
        return this.delete(`${API_BASE_URL}/${id}`);
    }
}

export default ApiService;
